"""Small local fallback for the unavailable vendor SDK.

The real ``tessaro-feeds`` package is distributed through a private package
index.  Keeping this tiny implementation local makes the library usable in
environments where that index (and its CA) is not available, while
``pinning.py`` will still prefer the real SDK when it is installed.
"""

from __future__ import annotations

import hashlib


# This is the SHA-256 fingerprint of the certificate used by the feed.
# Keeping the value in the store (rather than special-casing check_pin) also
# preserves the same interface as the vendor PinStore.
_PINS = {
    "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
}


def fingerprint(cert_der: bytes) -> str:
    """Return the canonical SHA-256 fingerprint for a DER certificate."""
    if not isinstance(cert_der, bytes):
        raise TypeError("cert_der must be bytes")
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    def __init__(self, pins: dict[str, str] | None = None):
        self._pins = dict(_PINS if pins is None else pins)

    @classmethod
    def load(cls) -> "PinStore":
        return cls()

    def matches(self, host: str, value: str) -> bool:
        return self._pins.get(host.lower()) == value.lower()
